param([switch]$AutoStart)
$ErrorActionPreference="Stop"
Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase,System.Windows.Forms,System.Drawing
$root=(Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path
$setupScript=Join-Path $PSScriptRoot "setup-performance-center.ps1"
$startScript=Join-Path $PSScriptRoot "start-supervised-performance-center.ps1"
$controlScript=Join-Path $PSScriptRoot "supervisor-control.ps1"
$wizardScript=Join-Path $PSScriptRoot "env-wizard.ps1"
$updateScript=Join-Path $PSScriptRoot "update-performance-center.ps1"
$stopScript=Join-Path $PSScriptRoot "stop-performance-center.ps1"
$edgeScript=Join-Path $PSScriptRoot "launch-edge.ps1"
$logPath=Join-Path $root "logs\supervisor.log"
. (Join-Path $PSScriptRoot "runtime-paths.ps1")
. (Join-Path $PSScriptRoot "native-operator-ui.ps1")
. (Join-Path $PSScriptRoot "launch-integration.ps1")
function Test-Backend {try{$r=Invoke-RestMethod "http://127.0.0.1:3000/api/v1/health" -TimeoutSec 2;return $r.status -eq "ok"}catch{return $false}}
function Get-Admin {try{Invoke-RestMethod "http://127.0.0.1:3000/api/v1/admin" -TimeoutSec 3}catch{$null}}
function Get-Lan {try{(Get-NetIPConfiguration|Where-Object {$_.IPv4DefaultGateway}|ForEach-Object {$_.IPv4Address.IPAddress}|Where-Object {$_ -and $_ -notmatch '^127\.|^169\.254\.'}|Select-Object -First 1)}catch{"<this-PC-IP>"}}
function Get-GrMetroUpdateSchedule([int]$InitialSeconds=20,[int]$RepeatSeconds=21600,[int[]]$FailureSeconds=@(300,1800,21600)){if($InitialSeconds-lt1-or$RepeatSeconds-lt60-or-not$FailureSeconds-or@($FailureSeconds|Where-Object{$_-lt60-or$_-gt21600}).Count){throw 'Invalid update-check schedule.'};[pscustomobject]@{InitialSeconds=$InitialSeconds;RepeatSeconds=$RepeatSeconds;FailureSeconds=$FailureSeconds}}
function Needs-Setup {(-not(Test-GrMetroPortableRuntime $root))-or(-not(Test-Path (Join-Path $root "node_modules\playwright\package.json")))-or(-not(Test-Path (Join-Path $root ".env")))-or(-not(Test-Path (Join-Path $root "apps\dashboard\dist\index.html")))}
function Run-HiddenWait($script,$arguments=@()){ $args=@('-STA','-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',('"{0}"' -f $script))+$arguments; $p=Start-Process powershell.exe -ArgumentList $args -WorkingDirectory $root -WindowStyle Hidden -PassThru -Wait; return $p.ExitCode }
function Start-Supervisor {if(Test-Backend){return};Start-Process powershell.exe -ArgumentList @('-STA','-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',('"{0}"' -f $startScript),'-SkipBuild') -WorkingDirectory $root -WindowStyle Hidden|Out-Null}
function Wait-Backend([bool]$wanted,[int]$seconds=40){$end=(Get-Date).AddSeconds($seconds);do{$ok=Test-Backend;if($ok -eq $wanted){return $true};Start-Sleep -Milliseconds 500;[System.Windows.Forms.Application]::DoEvents()}while((Get-Date)-lt $end);return $false}
function Installed-Version {try{$b=Get-Content (Join-Path $root 'scripts\windows\package-build.json') -Raw|ConvertFrom-Json;if($b.releaseVersion){[string]$b.releaseVersion}else{[string]$b.applicationVersion}}catch{'development'}}
function Version-Text {try{$b=Get-Content (Join-Path $root 'scripts\windows\package-build.json') -Raw|ConvertFrom-Json;$suffix=if($b.sourceState -eq 'working-tree'){' + working tree'}else{''};$version=if($b.releaseVersion){$b.releaseVersion}else{$b.applicationVersion};"v$version - $($b.commit)$suffix"}catch{try{$p=Get-Content (Join-Path $root 'package.json') -Raw|ConvertFrom-Json;"development-$($p.version)"}catch{'development'}}}
function ST-State($a){if(-not$a){return 'unknown'};$t=(($a.diagnostics.serviceTitan|ConvertTo-Json -Compress -Depth 5)+' '+($a.diagnostics.browser|ConvertTo-Json -Compress -Depth 5)).ToLowerInvariant();if($t -match 'login|sign.in|auth.*required|unauthorized|forbidden|session.*expired'){return 'login-required'};if($a.diagnostics.serviceTitan.status -eq 'connected' -and $a.diagnostics.browser.connected -and $a.diagnostics.browser.serviceTitanPageFound){return 'healthy'};'degraded'}
[xml]$xaml=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="GRMetro Performance Center" Width="1040" Height="820" MinWidth="940" MinHeight="700" WindowStartupLocation="CenterScreen" WindowState="Maximized" Background="#F4F7FB" FontFamily="Segoe UI" Foreground="#172033"><Window.Resources><Style x:Key="Tile" TargetType="Button"><Setter Property="Background" Value="White"/><Setter Property="BorderBrush" Value="#DCE3EC"/><Setter Property="BorderThickness" Value="1"/><Setter Property="Padding" Value="14"/><Setter Property="Margin" Value="5"/><Setter Property="HorizontalContentAlignment" Value="Left"/><Setter Property="Cursor" Value="Hand"/></Style></Window.Resources><Grid><Grid.RowDefinitions><RowDefinition Height="108"/><RowDefinition Height="*"/><RowDefinition Height="48"/></Grid.RowDefinitions><Border Background="#172033"><Grid Margin="30,0"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel Grid.Column="0" VerticalAlignment="Center"><TextBlock Text="GRMetro" Foreground="#75B8F4" FontSize="13" FontWeight="SemiBold"/><TextBlock Text="Performance Center" Foreground="White" FontSize="30" FontWeight="SemiBold"/><TextBlock Text="Native backend operations - ServiceTitan - display network" Foreground="#AEBCCE" FontSize="13"/></StackPanel><StackPanel Grid.Column="1" HorizontalAlignment="Right" VerticalAlignment="Center"><Border HorizontalAlignment="Right" Background="#26364C" CornerRadius="15" Padding="12,6"><StackPanel Orientation="Horizontal"><Ellipse x:Name="HeaderDot" Width="8" Height="8" Fill="#F0A400" Margin="0,0,8,0"/><TextBlock x:Name="HeaderText" Text="Checking" Foreground="White" FontWeight="SemiBold"/></StackPanel></Border><TextBlock x:Name="VersionText" Foreground="#94A5BA" Margin="0,7,0,0" HorizontalAlignment="Right"/></StackPanel></Grid></Border><ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto"><StackPanel Margin="30,24"><Border Background="White" BorderBrush="#E1E7EF" BorderThickness="1" CornerRadius="15" Padding="22"><Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="300"/></Grid.ColumnDefinitions><StackPanel><TextBlock Text="SYSTEM STATUS" Foreground="#758397" FontSize="11" FontWeight="SemiBold"/><StackPanel Orientation="Horizontal" Margin="0,8,0,0"><Ellipse x:Name="StatusDot" Width="12" Height="12" Fill="#F0A400" Margin="0,8,10,0"/><TextBlock x:Name="StatusLabel" Text="Checking..." FontSize="25" FontWeight="SemiBold"/></StackPanel><TextBlock x:Name="StatusDetail" Text="Reading backend health..." Foreground="#647287" FontSize="13" Margin="22,5,0,0" TextWrapping="Wrap"/><ProgressBar x:Name="Progress" Height="4" Margin="22,12,0,0" IsIndeterminate="True" Visibility="Collapsed"/></StackPanel><StackPanel Grid.Column="1" VerticalAlignment="Center"><Button x:Name="PrimaryButton" Content="CHECKING..." Height="46" Background="#0F6CBD" Foreground="White" FontWeight="SemiBold" BorderThickness="0" IsEnabled="False"/><Button x:Name="LoginButton" Content="OPEN SERVICETITAN LOGIN" Height="38" Margin="0,8,0,0" Visibility="Collapsed"/></StackPanel></Grid></Border><Border Background="White" BorderBrush="#E1E7EF" BorderThickness="1" CornerRadius="15" Padding="20" Margin="0,16,0,0"><Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><TextBlock Text="APPLICATION UPDATE" Foreground="#758397" FontSize="11" FontWeight="SemiBold"/><TextBlock x:Name="InstalledReleaseText" FontSize="13" FontWeight="SemiBold" Margin="0,7,0,0"/><TextBlock x:Name="UpdateStateText" Text="Checking for updates..." FontSize="20" FontWeight="SemiBold" Margin="0,5,0,0"/><TextBlock x:Name="AvailableReleaseText" Foreground="#0F6CBD" FontSize="14" FontWeight="SemiBold" Margin="0,3,0,0" Visibility="Collapsed"/><TextBlock x:Name="UpdateSummaryText" Foreground="#647287" FontSize="12" TextWrapping="Wrap" MaxWidth="620" Margin="0,4,0,0"/><ProgressBar x:Name="UpdateProgress" Height="5" Margin="0,12,0,0" Visibility="Collapsed"/></StackPanel><StackPanel Grid.Column="1" VerticalAlignment="Center" Margin="20,0,0,0"><Button x:Name="CheckUpdatesButton" Content="Check for Updates" Padding="14,7"/><Button x:Name="VersionHistoryButton" Content="Version History" Padding="14,7" Margin="0,8,0,0" Visibility="Collapsed"/><StackPanel x:Name="UpdateActions" Orientation="Horizontal" Margin="0,8,0,0" Visibility="Collapsed"><Button x:Name="ViewChangesButton" Content="View Changes" Padding="12,7" Margin="0,0,8,0"/><Button x:Name="UpdateNowButton" Content="Update Now" Padding="12,7" Background="#0F6CBD" Foreground="White"/></StackPanel></StackPanel></Grid></Border><Grid Margin="0,16,0,0"><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="14"/><ColumnDefinition/></Grid.ColumnDefinitions><Border Background="#EAF4FF" CornerRadius="11" Padding="16"><StackPanel><TextBlock Text="PHONE REMOTE" Foreground="#51779A" FontSize="10" FontWeight="SemiBold"/><TextBlock x:Name="RemoteUrl" FontFamily="Consolas" FontSize="12" Margin="0,5,0,0"/></StackPanel></Border><Border Grid.Column="2" Background="#F4F1FF" CornerRadius="11" Padding="16"><StackPanel><TextBlock Text="TV DISPLAY URL" Foreground="#6F5F9C" FontSize="10" FontWeight="SemiBold"/><TextBlock x:Name="DisplayUrl" FontFamily="Consolas" FontSize="12" Margin="0,5,0,0"/></StackPanel></Border></Grid><TextBlock Text="TOOLS" Foreground="#758397" FontSize="11" FontWeight="SemiBold" Margin="4,22,0,4"/><UniformGrid Columns="3"><Button x:Name="RemoteButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Phone Remote" FontWeight="SemiBold"/><TextBlock Text="Native access and QR" Foreground="#77869A" FontSize="11"/></StackPanel></Button><Button x:Name="AdminButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Admin Diagnostics" FontWeight="SemiBold"/><TextBlock Text="Open inside this app" Foreground="#77869A" FontSize="11"/></StackPanel></Button><Button x:Name="LogsButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Recovery Logs" FontWeight="SemiBold"/><TextBlock Text="View inside this app" Foreground="#77869A" FontSize="11"/></StackPanel></Button><Button x:Name="RefreshButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Refresh Data" FontWeight="SemiBold"/><TextBlock x:Name="RefreshDetail" Text="Fresh ServiceTitan sync" Foreground="#77869A" FontSize="11"/></StackPanel></Button><Button x:Name="RestartBackendButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Restart Backend" FontWeight="SemiBold"/><TextBlock x:Name="BackendDetail" Text="Restart backend only" Foreground="#77869A" FontSize="11"/></StackPanel></Button><Button x:Name="RestartBrowserButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Restart ServiceTitan" FontWeight="SemiBold"/><TextBlock x:Name="BrowserDetail" Text="Relaunch dedicated Edge" Foreground="#77869A" FontSize="11"/></StackPanel></Button><Button x:Name="UpdateButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Check for Updates" FontWeight="SemiBold"/><TextBlock Text="Signed release check" Foreground="#77869A" FontSize="11"/></StackPanel></Button><Button x:Name="ConfigButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Setup &amp; Configuration" FontWeight="SemiBold"/><TextBlock Text="Edit deployment settings" Foreground="#77869A" FontSize="11"/></StackPanel></Button><Button x:Name="FolderButton" Style="{StaticResource Tile}"><StackPanel><TextBlock Text="Program Folder" FontWeight="SemiBold"/><TextBlock Text="Open installation files" Foreground="#77869A" FontSize="11"/></StackPanel></Button></UniformGrid><TextBlock Text="LIVE ACTIVITY" Foreground="#758397" FontSize="11" FontWeight="SemiBold" Margin="4,20,0,6"/><Border Background="White" BorderBrush="#E1E7EF" BorderThickness="1" CornerRadius="11" Padding="14"><ListBox x:Name="ActivityList" BorderThickness="0" Background="Transparent" MaxHeight="130"/></Border></StackPanel></ScrollViewer><Border Grid.Row="2" Background="#EBEFF5" BorderBrush="#DDE4EC" BorderThickness="0,1,0,0"><Grid Margin="30,0"><StackPanel Orientation="Horizontal" VerticalAlignment="Center"><Button x:Name="ShortcutButton" Content="Desktop Shortcut" Padding="10,6" Margin="0,0,8,0"/><Button x:Name="MinimizeButton" Content="Minimize" Padding="10,6" Margin="0,0,8,0"/><Button x:Name="CloseButton" Content="Close Window" Padding="10,6"/></StackPanel><TextBlock x:Name="CheckedText" HorizontalAlignment="Right" VerticalAlignment="Center" Foreground="#8D99A8" FontSize="11"/></Grid></Border></Grid></Window>
'@
$window=[Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $xaml));function C($n){$window.FindName($n)}
$primary=C 'PrimaryButton';$statusLabel=C 'StatusLabel';$statusDetail=C 'StatusDetail';$statusDot=C 'StatusDot';$headerDot=C 'HeaderDot';$headerText=C 'HeaderText';$progress=C 'Progress';$login=C 'LoginButton';$activity=C 'ActivityList';$checked=C 'CheckedText';$refreshButton=C 'RefreshButton';$restartBackendButton=C 'RestartBackendButton';$restartBrowserButton=C 'RestartBrowserButton';$updateStateText=C 'UpdateStateText';$availableReleaseText=C 'AvailableReleaseText';$updateSummaryText=C 'UpdateSummaryText';$updateProgress=C 'UpdateProgress';$updateActions=C 'UpdateActions';$checkUpdatesButton=C 'CheckUpdatesButton';$versionHistoryButton=C 'VersionHistoryButton';$viewChangesButton=C 'ViewChangesButton';$updateNowButton=C 'UpdateNowButton';$lan=Get-Lan;$remote="http://${lan}:3000/remote"
$activity.IsHitTestVisible=$false;$activity.Focusable=$false;[System.Windows.Controls.ScrollViewer]::SetVerticalScrollBarVisibility($activity,[System.Windows.Controls.ScrollBarVisibility]::Disabled);[System.Windows.Controls.ScrollViewer]::SetCanContentScroll($activity,$false)
(C 'VersionText').Text=Version-Text;(C 'InstalledReleaseText').Text="Installed version  $(Installed-Version)";(C 'RemoteUrl').Text=$remote;(C 'DisplayUrl').Text="http://${lan}:3000/?display=<display-id>"
$script:lastState='';$script:primaryMode='start';$script:operatorActivity=New-Object System.Collections.Generic.List[string];$script:detailVersions=@{};$script:detailResets=@{};$script:nativeOperation=$null;$script:updateCheck=$null;$script:availableUpdate=$null;$script:releaseHistory=@();$script:updateStatusPath=$null;$script:updateStartedAt=$null;$script:allowWindowClose=$false;$script:autoCheckCompleted=$false;$script:updateFailureCount=0
function Add-Activity([string]$message,[string]$level='INFO'){ $script:operatorActivity.Insert(0,("{0}  {1}  {2}" -f (Get-Date -Format 'h:mm:ss tt'),$level,$message));while($script:operatorActivity.Count -gt 8){$script:operatorActivity.RemoveAt($script:operatorActivity.Count-1)} }
function Paint($title,$detail,$pill,$color){$statusLabel.Text=$title;$statusDetail.Text=$detail;$statusDot.Fill=[Windows.Media.BrushConverter]::new().ConvertFromString($color);$headerDot.Fill=$statusDot.Fill;$headerText.Text=$pill;$checked.Text="Last checked $(Get-Date -Format 'h:mm:ss tt')"}
function Set-PrimaryMode([string]$mode){$script:primaryMode=$mode;switch($mode){'stop'{$primary.Content='STOP PERFORMANCE CENTER';$primary.Background=[Windows.Media.BrushConverter]::new().ConvertFromString('#B42318');$primary.IsEnabled=$true}'setup'{$primary.Content='SET UP + START';$primary.Background=[Windows.Media.BrushConverter]::new().ConvertFromString('#0F6CBD');$primary.IsEnabled=$true}default{$primary.Content='START PERFORMANCE CENTER';$primary.Background=[Windows.Media.BrushConverter]::new().ConvertFromString('#0F6CBD');$primary.IsEnabled=$true}}}
function Refresh-Activity([bool]$online=$false,[string]$st='unknown'){$activity.Items.Clear();$backendText=if($online){'OK - Backend health check is responding'}else{'OFFLINE - Backend health check is not responding'};[void]$activity.Items.Add(("{0}  SYSTEM  {1}" -f (Get-Date -Format 'h:mm:ss tt'),$backendText));$stText=switch($st){'healthy'{'OK - ServiceTitan is connected and usable'}'login-required'{'ACTION - ServiceTitan needs a login'}'degraded'{'WARNING - ServiceTitan connection is degraded'}default{'UNKNOWN - ServiceTitan status unavailable'}};[void]$activity.Items.Add(("{0}  SYSTEM  {1}" -f (Get-Date -Format 'h:mm:ss tt'),$stText));foreach($line in $script:operatorActivity){[void]$activity.Items.Add($line)};if($script:operatorActivity.Count -eq 0){[void]$activity.Items.Add('No operator actions yet. GRMetro will report starts, stops, restarts, refreshes, and failures here.')}}
function Update-Status {if($script:nativeOperation){return};$online=Test-Backend;$a=if($online){Get-Admin}else{$null};$st=ST-State $a;$state=if($online -and $st -eq 'login-required'){'login'}elseif($online){'running'}elseif(Needs-Setup){'setup'}else{'ready'};switch($state){'running'{Paint 'Running' 'Backend healthy - ServiceTitan connected - self-healing active' 'ONLINE' '#198754';Set-PrimaryMode 'stop';$login.Visibility='Collapsed'}'login'{Paint 'ServiceTitan login required' 'Backend is running, but ServiceTitan needs you to sign in.' 'ACTION NEEDED' '#D97706';Set-PrimaryMode 'stop';$login.Visibility='Visible'}'ready'{Paint 'Ready to start' 'Setup is complete. Start the supervised backend and ServiceTitan browser.' 'READY' '#D97706';Set-PrimaryMode 'start';$login.Visibility='Collapsed'}'setup'{Paint 'First-time setup needed' 'Set up and start GRMetro.' 'SETUP' '#D97706';Set-PrimaryMode 'setup';$login.Visibility='Collapsed'}};Refresh-Activity $online $st}
function Busy($text){$progress.Visibility='Visible';$statusLabel.Text=$text;$primary.IsEnabled=$false;$window.Dispatcher.Invoke([action]{},'Background')}
function Set-DetailText($detail,[string]$text){$name=$detail.Name;$version=1+[int]($script:detailVersions[$name]);$script:detailVersions[$name]=$version;$script:detailResets.Remove($name);$detail.Text=$text;return $version}
function Set-TransientDetail($detail,[string]$text,[string]$defaultText,[int]$seconds=8){$version=Set-DetailText $detail $text;$script:detailResets[$detail.Name]=[pscustomobject]@{Control=$detail;Version=$version;DefaultText=$defaultText;Due=(Get-Date).AddSeconds($seconds)}}
function Done($detail,$text,$defaultText){Add-Activity $text 'SUCCESS';Show-GrMetroResult -Title 'GRMetro Performance Center' -Message $text -Success $true;Set-TransientDetail $detail "Done - $text" $defaultText;Update-Status}
function Set-NativeOperationInterlock([bool]$busy){foreach($control in @($primary,$login,$refreshButton,$restartBackendButton,$restartBrowserButton)){if($control){$control.IsEnabled=-not$busy}}}
function Get-NativeOperationError([string]$text,[string]$fallback){$line=@($text -split "`r?`n"|ForEach-Object{$_.Trim()}|Where-Object{$_ -and $_ -notmatch '^At .+\.ps1:'})[0];if(-not$line){$line=$fallback};if($root){$line=$line.Replace($root,'the installed application')};return $line.Substring(0,[Math]::Min(300,$line.Length))}
function Start-NativeOperation([string]$kind,[string]$scriptPath,[string[]]$arguments,$detail,[string]$workingText,[string]$defaultText,[string]$successText,[string]$failureTitle){
  if($script:nativeOperation){Show-GrMetroResult 'Operation in progress' 'Wait for the current operation to finish, then try again.' $false;return}
  $null=Set-DetailText $detail $workingText;Add-Activity $workingText 'WORKING';$progress.Visibility='Visible';$statusLabel.Text=$workingText;Set-NativeOperationInterlock $true
  $operationId=[guid]::NewGuid().ToString('N');$stdout=Join-Path ([IO.Path]::GetTempPath()) "grmetro-$operationId.out";$stderr=Join-Path ([IO.Path]::GetTempPath()) "grmetro-$operationId.err"
  try{$process=Start-Process powershell.exe -ArgumentList (@('-STA','-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',('"{0}"' -f $scriptPath))+$arguments) -WorkingDirectory $root -WindowStyle Hidden -RedirectStandardOutput $stdout -RedirectStandardError $stderr -PassThru
    $script:nativeOperation=[pscustomobject]@{Kind=$kind;Process=$process;Detail=$detail;DefaultText=$defaultText;SuccessText=$successText;FailureTitle=$failureTitle;StdOut=$stdout;StdErr=$stderr}
  }catch{$progress.Visibility='Collapsed';Set-NativeOperationInterlock $false;$null=Set-DetailText $detail 'Restart failed';Add-Activity ("$failureTitle`: $($_.Exception.Message)") 'ERROR';Show-GrMetroResult $failureTitle $_.Exception.Message $false;Update-Status}
}
function Set-UpdateCard([string]$State,[string]$Summary='',[string]$Latest=''){
  $updateStateText.Text=$State;$updateSummaryText.Text=$Summary
  if($Latest){$availableReleaseText.Text=$Latest;$availableReleaseText.Visibility='Visible'}else{$availableReleaseText.Visibility='Collapsed'}
  $updateActions.Visibility=if($script:availableUpdate-and$script:availableUpdate.updateAvailable){'Visible'}else{'Collapsed'}
}
function Set-AutomaticUpdateBackoff([bool]$Succeeded){if(-not$automaticUpdateTimer-or-not$updateSchedule){return};if($Succeeded){$script:updateFailureCount=0;$automaticUpdateTimer.Interval=[TimeSpan]::FromSeconds($updateSchedule.RepeatSeconds);return};$script:updateFailureCount++;$index=[Math]::Min($script:updateFailureCount-1,$updateSchedule.FailureSeconds.Count-1);$automaticUpdateTimer.Interval=[TimeSpan]::FromSeconds($updateSchedule.FailureSeconds[$index])}
function Start-UpdateCheck([bool]$Manual=$false){
  if($script:updateCheck-or$script:updateStatusPath){if($Manual){Show-GrMetroResult 'Application Update' 'An update operation is already in progress.' $false};return}
  $script:availableUpdate=$null;$script:releaseHistory=@();$versionHistoryButton.Visibility='Collapsed';$updateActions.Visibility='Collapsed';$updateProgress.Visibility='Visible';$updateProgress.IsIndeterminate=$true;Set-UpdateCard 'Checking for updates...'
  $id=[guid]::NewGuid().ToString('N');$stdout=Join-Path ([IO.Path]::GetTempPath()) "grmetro-update-check-$id.out";$stderr=$stdout+'.err'
  try{$process=Start-Process powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',('"{0}"'-f$updateScript),'-CheckOnly') -WorkingDirectory $root -WindowStyle Hidden -RedirectStandardOutput $stdout -RedirectStandardError $stderr -PassThru;$script:updateCheck=[pscustomobject]@{Process=$process;Manual=$Manual;StdOut=$stdout;StdErr=$stderr}}
  catch{$updateProgress.Visibility='Collapsed';Set-UpdateCard 'Unable to check for updates' 'The update checker could not start.';if($Manual){Show-GrMetroResult 'Update check failed' $_.Exception.Message $false}else{Set-AutomaticUpdateBackoff $false}}
}
function Complete-UpdateCheck {
  $operation=$script:updateCheck;if(-not$operation-or-not$operation.Process.HasExited){return}
  $stdout=if(Test-Path $operation.StdOut){Get-Content -LiteralPath $operation.StdOut -Raw}else{''};$stderr=if(Test-Path $operation.StdErr){Get-Content -LiteralPath $operation.StdErr -Raw}else{''};$exitCode=$operation.Process.ExitCode
  Remove-Item -LiteralPath $operation.StdOut,$operation.StdErr -Force -ErrorAction SilentlyContinue;$script:updateCheck=$null;$updateProgress.Visibility='Collapsed'
  if($null -ne $exitCode -and $exitCode -ne 0){$message=Get-NativeOperationError $stderr 'The configured release source could not be reached or verified.';Set-UpdateCard 'Unable to check for updates' $message;if($operation.Manual){Show-GrMetroResult 'Update check failed' $message $false}else{Set-AutomaticUpdateBackoff $false};return}
  try{$json=@($stdout-split"`r?`n"|Where-Object{$_.Trim().StartsWith('{')})|Select-Object -Last 1;$result=$json|ConvertFrom-Json}catch{Set-UpdateCard 'Unable to check for updates' 'The Update Host returned an invalid response.';if($operation.Manual){Show-GrMetroResult 'Update check failed' 'The Update Host returned an invalid response.' $false}else{Set-AutomaticUpdateBackoff $false};return}
  $script:releaseHistory=@($result.versionHistory)
  $versionHistoryButton.Visibility=if($script:releaseHistory.Count){'Visible'}else{'Collapsed'}
  if(-not$operation.Manual){Set-AutomaticUpdateBackoff $true}
  switch([string]$result.status){
    'available'{$script:availableUpdate=$result;Set-UpdateCard 'Update available' ([string]$result.summary) ([string]$result.latest);Add-Activity "Update $($result.latest) is available." 'INFO'}
    'requires-setup'{Set-UpdateCard 'Setup update required' ([string]$result.message) ([string]$result.latest)}
    'not-configured'{Set-UpdateCard 'Update source not configured' 'Remote releases are disabled until a trusted source is provisioned.'}
    default{Set-UpdateCard 'Up to date' "Installed release $($result.current) is current.";if($operation.Manual){Add-Activity 'Manual update check found no newer release.' 'SUCCESS'}}
  }
}
function Start-RemoteUpdate {
  if(-not$script:availableUpdate-or-not$script:availableUpdate.updateAvailable){return}
  if(-not(Confirm-GrMetroAction 'Install GRMetro Update' "Install GRMetro $($script:availableUpdate.latest)?`n`nGRMetro will prepare a verified rollback backup, briefly stop the dashboard, install the update, validate it, and reopen the Control Center.")){return}
  $stateRoot=Join-Path $env:LOCALAPPDATA 'GRMetro\Update State';New-Item -ItemType Directory -Force -Path $stateRoot|Out-Null;$script:updateStatusPath=Join-Path $stateRoot ('operation-'+[guid]::NewGuid().ToString('N')+'.json');$script:updateStartedAt=Get-Date
  $updateProgress.Visibility='Visible';$updateProgress.IsIndeterminate=$true;$checkUpdatesButton.IsEnabled=$false;$updateNowButton.IsEnabled=$false;$viewChangesButton.IsEnabled=$false;Set-UpdateCard 'Starting update...' 'The Control Center remains available while the package is verified and prepared.' ([string]$script:availableUpdate.latest)
  try{Start-Process powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',('"{0}"'-f$updateScript),'-InstallRemote','-ParentProcessId',[string]$PID,'-ExpectedReleaseVersion',[string]$script:availableUpdate.latest,'-StatusPath',('"{0}"'-f$script:updateStatusPath)) -WorkingDirectory $root -WindowStyle Hidden|Out-Null;Add-Activity "Preparing update $($script:availableUpdate.latest)." 'WORKING'}
  catch{$script:updateStatusPath=$null;$updateProgress.Visibility='Collapsed';$checkUpdatesButton.IsEnabled=$true;$updateNowButton.IsEnabled=$true;$viewChangesButton.IsEnabled=$true;Set-UpdateCard 'Update failed to start' $_.Exception.Message ([string]$script:availableUpdate.latest);Show-GrMetroResult 'Update failed to start' $_.Exception.Message $false}
}
function Update-RemoteProgress {
  if(-not$script:updateStatusPath){return}
  if(-not(Test-Path -LiteralPath $script:updateStatusPath -PathType Leaf)){if(((Get-Date)-$script:updateStartedAt).TotalSeconds-gt20){Set-UpdateCard 'Update failed to start' 'The external Update Host did not report progress.';Show-GrMetroResult 'Update failed' 'The external Update Host did not report progress.' $false;$script:updateStatusPath=$null};return}
  try{$state=Get-Content -LiteralPath $script:updateStatusPath -Raw|ConvertFrom-Json}catch{return}
  $updateStateText.Text=[string]$state.message
  if([int]$state.percent-ge0){$updateProgress.IsIndeterminate=$false;$updateProgress.Value=[Math]::Min(100,[Math]::Max(0,[int]$state.percent))}else{$updateProgress.IsIndeterminate=$true}
  if([string]$state.stage-eq'ready-to-install'){$script:allowWindowClose=$true;$window.Close();return}
  if([string]$state.stage-in@('failed','rollback-failed')){$updateProgress.Visibility='Collapsed';$checkUpdatesButton.IsEnabled=$true;$updateNowButton.IsEnabled=$true;$viewChangesButton.IsEnabled=$true;Show-GrMetroResult 'GRMetro update failed' ([string]$state.message) $false;$script:updateStatusPath=$null}
}
