function Show-GrMetroVersionHistory {
  if(-not$script:releaseHistory.Count){Show-GrMetroResult 'Version History' 'No verified release history is available yet.' $false;return}
  $lines=New-Object Collections.Generic.List[string]
  foreach($entry in $script:releaseHistory){
    $status=switch([string]$entry.status){'installed'{'Installed'}'available'{'Available'}default{'Previously verified'}}
    $lines.Add("$($entry.version) - $status")
    if($entry.date){try{$date=[DateTimeOffset]::Parse([string]$entry.date).ToLocalTime().ToString('MMMM d, yyyy');$lines.Add("$(([string]$entry.dateSource).Substring(0,1).ToUpper()+([string]$entry.dateSource).Substring(1)) $date")}catch{$lines.Add('Date unavailable')}}else{$lines.Add('Date unavailable')}
    if(@($entry.releaseNotes).Count){foreach($note in @($entry.releaseNotes)){$lines.Add("* $note")}}else{$lines.Add('Release notes unavailable for this verified version.')}
    $lines.Add('')
  }
  $lines.Add('Restore Version is not available yet. Automatic failed-update rollback remains active.')
  Show-GrMetroTextDialog -Title 'GRMetro Version History' -Heading 'Verified releases' -Text ($lines-join[Environment]::NewLine) -ActionLabel 'Close'
}
